{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "It defines a classroom library as materials acquired by a teacher and made available to their students.",
      "rationale": "Conveys teacher acquisition and student access, but omits the requirement that materials be made available in that teacher's classroom to students assigned to the teacher's classes."
    },
    {
      "proposition_id": "P2",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not explain the definition of a library collection, including its school scope and exclusions for course curriculum and classroom-library materials."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "Materials include items such as books, films, video games, and subscription content.",
      "rationale": "Identifies several covered formats but does not convey the definition's full scope, including applications and the other listed print, documentary, and recorded formats."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "The bill also amends existing law to ensure that procedures for referring and removing materials apply to classroom libraries as well as school library collections.",
      "rationale": "Conveys an extension to classroom libraries but does not identify the amendments to § 49-6-3803(a), (f), and (g). The supplied bill provides insertions, not the underlying procedures, so this description does not fully identify the amendment targets."
    },
    {
      "proposition_id": "P5",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not mention deletion of § 49-6-3803(b)."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Local boards of education and public charter school governing bodies would be required to adopt policies for developing and reviewing both school library collections and classroom libraries.",
      "rationale": "Conveys the required policy adoption, responsible governing bodies, and coverage of both types of libraries."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "These policies must include a procedure for teachers, parents, and legal guardians to review and refer classroom library materials for evaluation.",
      "rationale": "Conveys the review and referral procedure but omits the limitation to parents and legal guardians of students with access to the classroom library."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "They must also provide parents and legal guardians multiple opportunities each school year to view the books in their student's classroom libraries.",
      "rationale": "Conveys repeated opportunities during the school year for parents and guardians to view books in their own student's classroom libraries."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "Additionally, the policies must prohibit teachers from intentionally bypassing library collection policies using their classroom libraries, such as by including materials deemed inappropriate for students' age and maturity levels or unsuitable for the school's educational mission.",
      "rationale": "Conveys the anti-circumvention prohibition and examples, but omits knowing circumvention and the specified authorities whose findings establish the examples' inappropriateness or unsuitability."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "This act would take effect upon becoming law.",
      "rationale": "Accurately conveys the effective date."
    }
  ]
}
